import{_ as o,o as e,c as d,ag as a}from"./chunks/framework.BaNuf0sO.js";const u=JSON.parse('{"title":"AiOperationBar（内部件 · 仅 API）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/agent/src/components/operation/docs/README-AiOperationBar.md","filePath":"docs/agent/src/components/operation/docs/README-AiOperationBar.md"}'),r={name:"docs/agent/src/components/operation/docs/README-AiOperationBar.md"};function i(c,t,s,n,l,h){return e(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="aioperationbar-内部件-·-仅-api" tabindex="-1">AiOperationBar（内部件 · 仅 API） <a class="header-anchor" href="#aioperationbar-内部件-·-仅-api" aria-label="Permalink to &quot;AiOperationBar（内部件 · 仅 API）&quot;">​</a></h1><blockquote><p>内部件，[MUST NOT] 当公共组件用。折叠式会话操作条：左/右侧竖条 = AiOperationBtns（logo + 关闭 + 展开收起 + 新建会话）+ 展开区 = Conversations 会话列表（按日期分组 / 分页加载 / 点选切换）。AiDialogueGroup 装配。</p></blockquote><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><blockquote><p>⚠️ 以 types.ts（<code>AiOperationBarProps</code>）与组件源码为真相源；与文档冲突时以源码为准。</p></blockquote><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>type</th><th>默认</th><th>语义</th></tr></thead><tbody><tr><td><code>position</code></td><td><code>&quot;left&quot;|&quot;right&quot;?</code></td><td><code>&quot;right&quot;</code></td><td>操作条位置</td></tr><tr><td><code>collapsedWidth</code></td><td><code>number|string?</code></td><td><code>50</code></td><td>折叠宽度</td></tr><tr><td><code>unCollapseWidth</code></td><td><code>number|string?</code></td><td><code>200</code></td><td>展开宽度</td></tr><tr><td><code>onClose</code></td><td><code>(() =&gt; void)?</code></td><td>—</td><td>关闭回调（传入则显示关闭按钮；<code>tooltipPlacement</code> 相应联动）</td></tr><tr><td><code>logoUrl</code></td><td><code>string?</code></td><td>—</td><td>logo 图片地址（优先级 <code>#logo</code> 槽 &gt; logoUrl &gt; 色块占位）</td></tr><tr><td><code>list</code></td><td><code>XConversationItem[]</code>（必填）</td><td>—</td><td>会话列表（AiDialogueGroup 注入）</td></tr><tr><td><code>sessionListLoadMoreLoading</code></td><td><code>boolean?</code></td><td><code>false</code></td><td>会话列表分页加载中</td></tr></tbody></table><p><strong>v-model</strong>：<code>activeSessionId</code>（string，激活会话）/ <code>isCollapsed</code>（boolean，折叠态，默认 <code>true</code>）</p><h3 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>事件</th><th>参数</th><th>语义</th></tr></thead><tbody><tr><td><code>sessionListLodeMore</code></td><td>—</td><td>会话列表滚动到底请求下一页（注意：emit 名为源仓遗留拼写 <code>Lode</code>）</td></tr></tbody></table><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><table tabindex="0"><thead><tr><th>槽</th><th>scope</th><th>语义</th></tr></thead><tbody><tr><td><code>#logo</code></td><td><code>{ size: string, mode: &quot;ai&quot; }</code></td><td>logo 渲染口（透传给 AiOperationBtns）</td></tr></tbody></table><h3 id="expose" tabindex="-1">Expose <a class="header-anchor" href="#expose" aria-label="Permalink to &quot;Expose&quot;">​</a></h3><p>无</p><h2 id="机制契约" tabindex="-1">机制契约 <a class="header-anchor" href="#机制契约" aria-label="Permalink to &quot;机制契约&quot;">​</a></h2><ul><li>展开状态下点选会话 → <code>@update:active</code> → 内部 <code>hideBar</code> 立即收起（显式操作后收起）</li><li><strong>0.3.0 起不再有「悬停主体区自动收起」</strong>（原 <code>useGroupUX</code> 300ms 防抖）——鼠标飘过即消失属反直觉交互，业界会话列表为常驻或显式切换</li><li>会话按日期分组（<code>Conversations groupable</code>）：今天 / 更早（<code>formatTimestamp</code> 按 <code>YYYY-MM-DD</code> 分组标题）</li><li><code>tooltipPlacement</code> 由 position 派生（left → right，right → left），无需外部传</li><li><strong>空列表态（q21yfk 判据 9）</strong>：无会话时弱化文案「暂无会话记录」（<code>--dc-agent-text-secondary</code>），[MUST NOT] 用 ElEmpty 纸箱插画——这是会话历史侧栏不是后台空态页</li></ul>',15)])])}const b=o(r,[["render",i]]);export{u as __pageData,b as default};
